/// <reference types="node" />
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

// brandPaths.ts is generated by docs/brand/generate.py (docs/brand.md).
// This fails if someone edits it by hand, or changes the geometry in the
// generator without re-running it.
describe("brandPaths.ts", () => {
  it("matches docs/brand/generate.py", () => {
    const root = process.cwd();
    const generated = execFileSync("python3", [join(root, "docs/brand/generate.py"), "--paths"], { encoding: "utf8" });
    expect(readFileSync(join(root, "src/ui/brandPaths.ts"), "utf8")).toBe(generated);
  });
});
